                  <strong>{statistic.batting?.runsScored}</strong>
                  <span>
                    {statistic.batting?.ballsFaced} balls Â· SR{' '}
                    {formatRate(statistic.batting?.strikeRate ?? null)}
                  </span>
                </li>
              ))}
