            <td data-numeric>{aggregate.appearances}</td>
            <td data-numeric>{aggregate.batting?.runsScored ?? 'â€”'}</td>
            <td data-numeric>{formatRate(aggregate.batting?.battingAverage ?? null)}</td>
            <td data-numeric>{formatRate(aggregate.batting?.strikeRate ?? null)}</td>
            <td data-numeric>{aggregate.batting ? highestScore(aggregate.batting) : 'â€”'}</td>
            <td data-numeric>{aggregate.batting?.fifties ?? 'â€”'}</td>
            <td data-numeric>{aggregate.batting?.hundreds ?? 'â€”'}</td>
            <td data-numeric>{aggregate.bowling?.wicketsTaken ?? 'â€”'}</td>
            <td data-numeric>{formatRate(aggregate.bowling?.economyRate ?? null)}</td>
          </tr>
        ))}
      </tbody>
    </DataTable>
  );
}

function CompetitionTable({ competitions }: { competitions: ParticipantCompetitionAggregate[] }) {
  if (competitions.length === 0) {
    return (
      <p className="statistics-section__empty" role="status">
        No competition aggregates are available.
      </p>
    );
  }
  return (
    <DataTable caption="Participant record by competition">
      <thead>
        <tr>
          <th scope="col">Competition</th>
          <th scope="col" data-numeric>
            Mat
          </th>
          <th scope="col" data-numeric>
            Runs
          </th>
          <th scope="col" data-numeric>
            Avg
          </th>
          <th scope="col" data-numeric>
            SR
          </th>
          <th scope="col" data-numeric>
            HS
          </th>
          <th scope="col" data-numeric>
            50s
          </th>
          <th scope="col" data-numeric>
            100s
          </th>
          <th scope="col" data-numeric>
            Wkts
          </th>
          <th scope="col" data-numeric>
            Econ
          </th>
        </tr>
      </thead>
      <tbody>
        {competitions.map((aggregate) => (
          <tr key={aggregate.statisticId}>
            <th scope="row">
              {aggregate.competitionId && aggregate.competitionName ? (
                <Link to={`/competitions/${encodeURIComponent(aggregate.competitionId)}`}>
                  {aggregate.competitionName}
                </Link>
              ) : (
                (aggregate.competitionName ?? 'Competition unavailable')
              )}
            </th>
            <td data-numeric>{aggregate.appearances}</td>
            <td data-numeric>{aggregate.batting?.runsScored ?? 'â€”'}</td>
            <td data-numeric>{formatRate(aggregate.batting?.battingAverage ?? null)}</td>
            <td data-numeric>{formatRate(aggregate.batting?.strikeRate ?? null)}</td>
            <td data-numeric>{aggregate.batting ? highestScore(aggregate.batting) : 'â€”'}</td>
            <td data-numeric>{aggregate.batting?.fifties ?? 'â€”'}</td>
            <td data-numeric>{aggregate.batting?.hundreds ?? 'â€”'}</td>
            <td data-numeric>{aggregate.bowling?.wicketsTaken ?? 'â€”'}</td>
            <td data-numeric>{formatRate(aggregate.bowling?.economyRate ?? null)}</td>
          </tr>
        ))}
      </tbody>
    </DataTable>
  );
}

export function ParticipantAggregateView({ aggregates }: { aggregates: ParticipantAggregates }) {
  const [scope, setScope] = useState<ParticipantScope>('career');
  const tabsId = useId();
  const career = aggregates.statistics.find(
    (statistic): statistic is ParticipantCareerAggregate => statistic.scope === 'career',
  );
  const competitions = aggregates.statistics.filter(
    (statistic): statistic is ParticipantCompetitionAggregate => statistic.scope === 'competition',
  );
  const seasons = aggregates.statistics.filter(
    (statistic): statistic is ParticipantSeasonAggregate => statistic.scope === 'season',
  );
  const scopes: { id: ParticipantScope; label: string }[] = [
    { id: 'career', label: 'Career' },
    { id: 'competition', label: 'By competition' },
    { id: 'season', label: 'By season' },
  ];

  return (
    <>
      <div className="statistics-section-heading">
        <div>
          <p className="eyebrow">Published player record</p>
          <h3>Career overview</h3>
        </div>
        <p className={`statistics-status statistics-status--${aggregates.status}`}>
          {aggregates.status === 'complete' ? 'Complete data' : 'Partial data'}
        </p>
      </div>
      {aggregates.warnings.length > 0 ? (
        <section className="statistics-warnings" aria-label="Data notices" role="status">
          <h3>Data notices</h3>
          <ul>
            {aggregates.warnings.map((warning, index) => (
              <li key={`${warning.code}-${index}`}>{warning.message}</li>
            ))}
          </ul>
        </section>
      ) : null}
      {career ? (
        <CareerOverview career={career} />
      ) : (
        <div className="state-message" role="status">
          <h3>No career totals available</h3>
          <p>No career batting or bowling figures are published for this player.</p>
        </div>
      )}
      <section aria-labelledby={`${tabsId}-heading`} className="participant-scope-section">
        <div className="statistics-section-heading">
          <div>
            <p className="eyebrow">Current scope</p>
            <h3 id={`${tabsId}-heading`}>Explore the record</h3>
          </div>
        </div>
        <div className="statistics-tabs" role="tablist" aria-label="Player statistics scope">
          {scopes.map((item, index) => (
            <button
              aria-controls={`${tabsId}-${item.id}-panel`}
              aria-selected={scope === item.id}
              className="statistics-tab"
              id={`${tabsId}-${item.id}-tab`}
              key={item.id}
              onClick={() => setScope(item.id)}
              onKeyDown={(event) => {
                let nextIndex: number | null = null;
                if (event.key === 'ArrowRight' || event.key === 'ArrowDown') {
                  nextIndex = (index + 1) % scopes.length;
                } else if (event.key === 'ArrowLeft' || event.key === 'ArrowUp') {
                  nextIndex = (index - 1 + scopes.length) % scopes.length;
                } else if (event.key === 'Home') {
                  nextIndex = 0;
                } else if (event.key === 'End') {
                  nextIndex = scopes.length - 1;
                }
                if (nextIndex === null) return;
                event.preventDefault();
                const nextScope = scopes[nextIndex];
                if (!nextScope) return;
                setScope(nextScope.id);
                document.getElementById(`${tabsId}-${nextScope.id}-tab`)?.focus();
              }}
              role="tab"
              tabIndex={scope === item.id ? 0 : -1}
              type="button"
            >
              {item.label}
            </button>
          ))}
        </div>
        <div
          aria-labelledby={`${tabsId}-${scope}-tab`}
          className="statistics-tab-panel"
          id={`${tabsId}-${scope}-panel`}
          role="tabpanel"
          tabIndex={0}
        >
          <p className="scope-description">
            {scope === 'career'
              ? 'All published standard-innings records.'
              : scope === 'competition'
                ? 'Published totals grouped by competition.'
                : 'Published totals grouped by season and competition.'}
          </p>
          {scope === 'career' ? (
            career ? (
              <AggregateDetail aggregate={career} />
            ) : (
              <p className="statistics-section__empty">No career aggregate is available.</p>
            )
          ) : null}
          {scope === 'competition' ? <CompetitionTable competitions={competitions} /> : null}
          {scope === 'season' ? <SeasonTable seasons={seasons} /> : null}
        </div>
      </section>
      <section
        aria-labelledby={`${tabsId}-details-heading`}
        className="statistics-section calculation-details"
      >
        <div className="statistics-section-heading">
          <div>
            <p className="eyebrow">Evidence and scope</p>
            <h3 id={`${tabsId}-details-heading`}>Calculation details</h3>
          </div>
        </div>
        <details>
          <summary>How this player record is calculated</summary>
          <p>
            Aggregates use accepted events from standard innings. Super overs are excluded. Rates
            are calculated by the backend across the complete selected scope.
          </p>
          {career ? (
            <p>
              Career record: {career.appearances} appearances, {career.fixtureCount} batting or
              bowling matches and {career.sourceEventCount} accepted source events.
            </p>
          ) : null}
        </details>
        <StatisticsDefinitions
          includeBattingAverage
          includeBowlingAverage
          includeBowlingStrikeRate
        />
      </section>
    </>
  );
}
import type {
  FixtureStatistic,
  FixtureStatistics,
  ParticipantAggregateBowling,
  ParticipantFixtureBatting,
  ParticipantFixtureBowling,
  StatisticContributingEvent,
} from '@sport-analytics/contracts';
import { useCallback, useId, type ReactNode } from 'react';
import { Link, useParams } from 'react-router-dom';
import { Breadcrumbs, LocalNavigation } from '../../components/NavigationPrimitives';
import { publicReadApi } from '../../api/public-read';
import { DetailError, DetailLoading, RelatedLinks } from '../browse/RecordDetail';
import { SectionBoundary, SectionError } from '../browse/SectionBoundary';
import { usePublicData } from '../browse/usePublicData';
import { EventExportControls } from './EventExportControls';
import { FixtureAnalytics } from './FixtureScorecards';
import { ParticipantAggregateView } from './ParticipantAggregateView';

function recordPath(resource: 'competitors' | 'participants', identifier: string) {
  return `/${resource}/${encodeURIComponent(identifier)}`;
}

function fixtureLabel(statistics: FixtureStatistics): string {
  const names = statistics.statistics
    .map((statistic) => statistic.competitorName)
    .filter((name): name is string => Boolean(name));
  const distinctNames = [...new Set(names)];
  return distinctNames.length > 0 ? distinctNames.join(' vs ') : 'Fixture';
}

function StatisticMetric({ label, value }: { label: string; value: ReactNode }) {
  return (
    <div>
      <dt>{label}</dt>
      <dd>{value}</dd>
    </div>
  );
}

function MetricList({ children }: { children: ReactNode }) {
  return <dl className="statistic-metrics">{children}</dl>;
}

export function PlayerPerformance({
  batting,
  bowling,
  battingPosition,
  battingParticipation,
  dismissal,
  showUnavailable = false,
}: {
  batting: ParticipantFixtureBatting | null;
  bowling: ParticipantFixtureBowling | ParticipantAggregateBowling | null;
  battingPosition?: number | null;
  battingParticipation?: 'did_not_bat' | 'batted';
  dismissal?: {
    status: 'not_out' | 'dismissed';
    kind: string | null;
    eventId: string | null;
  } | null;
  showUnavailable?: boolean;
}) {
  return (
    <div className="participant-statistics">
      {batting ? (
        <section aria-label="Batting statistics">
          <h4>Batting</h4>
          <MetricList>
            {battingPosition !== null && battingPosition !== undefined ? (
              <StatisticMetric label="Batting position" value={battingPosition} />
            ) : null}
            <StatisticMetric
              label="Runs"
              value={
                dismissal?.status === 'not_out' ? (
                  <span aria-label={`${batting.runsScored} not out`}>{batting.runsScored}*</span>
                ) : (
                  batting.runsScored
                )
              }
            />
            <StatisticMetric label="Balls faced" value={batting.ballsFaced} />
            <StatisticMetric label="Strike rate" value={batting.strikeRate ?? 'â€”'} />
            <StatisticMetric label="Fours" value={batting.fours} />
            <StatisticMetric label="Sixes" value={batting.sixes} />
            {dismissal?.status === 'dismissed' ? (
              <StatisticMetric label="Dismissal" value={dismissal.kind ?? 'Dismissed'} />
            ) : null}
          </MetricList>
        </section>
      ) : battingParticipation === 'did_not_bat' ? (
        <section aria-label="Batting statistics">
          <h4>Batting</h4>
          <p className="statistics-section__empty">Did not bat</p>
        </section>
      ) : showUnavailable ? (
        <section aria-label="Batting statistics">
          <h4>Batting</h4>
          <p className="statistics-section__empty">No batting figures are available.</p>
        </section>
      ) : null}
      {bowling ? (
        <section aria-label="Bowling statistics">
          <h4>Bowling</h4>
          <MetricList>
            <StatisticMetric label="Runs conceded" value={bowling.runsConceded} />
            <StatisticMetric label="Wides" value={bowling.wides} />
            <StatisticMetric label="No-balls" value={bowling.noBalls} />
            <StatisticMetric label="Overs" value={bowling.oversBowled ?? 'â€”'} />
            <StatisticMetric label="Economy rate" value={bowling.economyRate ?? 'â€”'} />
            <StatisticMetric label="Wickets" value={bowling.wicketsTaken} />
          </MetricList>
        </section>
      ) : showUnavailable ? (
        <section aria-label="Bowling statistics">
          <h4>Bowling</h4>
          <p className="statistics-section__empty">Did not bowl</p>
        </section>
      ) : null}
    </div>
  );
}

function StatisticValues({ statistic }: { statistic: FixtureStatistic }) {
  if (statistic.scope === 'innings') {
    return (
      <MetricList>
        <StatisticMetric label="Runs" value={statistic.metrics.totalRuns} />
        {statistic.metrics.penaltyRuns > 0 ? (
          <StatisticMetric label="Penalty runs" value={statistic.metrics.penaltyRuns} />
        ) : null}
      </MetricList>
    );
  }
  return (
    <PlayerPerformance
      batting={statistic.batting}
      bowling={statistic.bowling}
      battingPosition={statistic.battingPosition}
      battingParticipation={statistic.battingParticipation}
      dismissal={statistic.dismissal}
    />
  );
}

function StatisticsContent({
  statistics,
  retry,
}: {
  statistics: FixtureStatistics;
  retry(): void;
}) {
  const fixturePath = `/fixtures/${encodeURIComponent(statistics.fixtureId)}`;
  return (
    <article className="detail-page statistics-page content-boundary">
      <Breadcrumbs
        items={[
          { label: 'Fixtures', to: '/fixtures' },
          { label: fixtureLabel(statistics), to: fixturePath },
          { label: 'Statistics', to: '#' },
        ]}
      />
      <Link className="back-link" to={fixturePath}>
        Back to match overview
      </Link>
      <header className="page-heading page-heading--detail">
        <p className="eyebrow">Published match record</p>
        <h1>Match statistics</h1>
        <p>Cricket scorecards calculated from accepted delivery events.</p>
        <Link
          className="button button--secondary"
          to={`/participants/compare?fixtureId=${encodeURIComponent(statistics.fixtureId)}`}
        >
          Compare player performances
        </Link>
      </header>
      <LocalNavigation
        label="Fixture sections"
        items={[
          { label: 'Overview', to: fixturePath },
          { label: 'Statistics', to: `${fixturePath}/statistics` },
          { label: 'Players', to: `${fixturePath}/players` },
        ]}
      />
      <div className="fixture-statistics-overview">
        <SectionBoundary
          onRetry={retry}
          renderError={(boundaryRetry) => (
            <StatisticsSectionError
              reason="The published statistics could not be displayed."
              retry={boundaryRetry}
            />
          )}
        >
          <FixtureAnalytics statistics={statistics} />
        </SectionBoundary>
      </div>
    </article>
  );
}

function StatisticsSectionError({ reason, retry }: { reason: string; retry(): void }) {
  return (
    <SectionError
      description="Published match statistics could not be requested. Try this section again."
      reason={reason}
      retry={retry}
      retryLabel="Retry match statistics"
      title="Match statistics could not be loaded"
    />
  );
}

export function FixtureStatisticsOverview({ fixtureId }: { fixtureId: string }) {
  const headingId = useId();
  const load = useCallback(
    (signal: AbortSignal) => publicReadApi.getFixtureStatistics(fixtureId, signal),
    [fixtureId],
  );
  const state = usePublicData(load, fixtureId);
  return (
    <section aria-labelledby={headingId} className="related-collection fixture-statistics-overview">
      <div className="statistics-section-heading">
        <div>
          <p className="eyebrow">Published match record</p>
          <h2 id={headingId}>Match statistics</h2>
        </div>
      </div>
      {state.status === 'loading' ? (
        <div className="state-message" role="status">
          <h3>Loading match statistics</h3>
          <p>The published outcome and player performances are being requested.</p>
        </div>
      ) : null}
      {state.status === 'error' ? (
        <StatisticsSectionError reason={state.error.message} retry={state.reload} />
      ) : null}
      {state.status === 'ready' ? (
        <SectionBoundary
          onRetry={state.reload}
          renderError={(retry) => (
            <StatisticsSectionError
              reason="The published statistics could not be displayed."
              retry={retry}
            />
          )}
        >
          <FixtureAnalytics statistics={state.data.data} />
        </SectionBoundary>
      ) : null}
    </section>
  );
}

function ParticipantStatisticsError({ reason, retry }: { reason: string; retry(): void }) {
  return (
    <SectionError
      description="Published career totals could not be requested. Try this section again."
      reason={reason}
      retry={retry}
      retryLabel="Retry career totals"
      title="Career totals could not be loaded"
    />
  );
}

export function ParticipantCareerOverview({ participantId }: { participantId: string }) {
  const headingId = useId();
  const load = useCallback(
    (signal: AbortSignal) =>
      publicReadApi.getParticipantAggregates(participantId, undefined, signal),
    [participantId],
  );
  const state = usePublicData(load, participantId);
  return (
    <section
      aria-labelledby={headingId}
      className="related-collection participant-aggregate-overview"
    >
      <div className="statistics-section-heading">
        <div>
          <p className="eyebrow">Published player statistics</p>
          <h2 id={headingId}>Career totals</h2>
        </div>
      </div>
      {state.status === 'loading' ? (
        <div className="state-message" role="status">
          <h3>Loading career totals</h3>
          <p>The career, competition and season records are being requested.</p>
        </div>
      ) : null}
      {state.status === 'error' ? (
        <ParticipantStatisticsError reason={state.error.message} retry={state.reload} />
      ) : null}
      {state.status === 'ready' ? (
        <SectionBoundary
          onRetry={state.reload}
          renderError={(retry) => (
            <ParticipantStatisticsError
              reason="The published player statistics could not be displayed."
              retry={retry}
            />
          )}
        >
          <ParticipantAggregateView aggregates={state.data.data} />
        </SectionBoundary>
