}

function EventTrace({ event }: { event: StatisticContributingEvent }) {
  return (
    <li className="event-trace">
      <header>
        <p className="record-list__meta">Innings {event.inningsOrdinal}</p>
        <h3>Delivery {event.sequenceNumber}</h3>
