                </Link>
                <span>
                  {scorer.runsScored}
                  {scorer.notOut ? '*' : ''} runs Â· innings {scorer.inningsOrdinal + 1}
                </span>
              </li>
            ))}
          </ul>
        </section>
      ) : null}
