}

function CalculationDetails({ statistics }: { statistics: FixtureStatistics }) {
  return (
    <section
      aria-labelledby="calculation-details-heading"
      className="statistics-section calculation-details"
    >
      <div className="statistics-section-heading">
        <div>
          <p className="eyebrow">Evidence and scope</p>
          <h3 id="calculation-details-heading">Calculation details</h3>
        </div>
      </div>
      <details>
        <summary>How these match statistics are calculated</summary>
        <p>
          Figures use accepted delivery events from standard innings. Super overs are excluded. Runs
          conceded include runs off the bat, wides and no-balls; ordinary byes and leg-byes are
          excluded.
        </p>
        <ul>
          {statistics.statistics.map((statistic) => (
            <li key={statistic.statisticId}>
              <span>
                {statistic.scope === 'innings'
                  ? statistic.competitorName
                  : statistic.participantName}
                : {statistic.sourceEventCount} accepted{' '}
                {statistic.sourceEventCount === 1 ? 'event' : 'events'}
              </span>{' '}
              <Link
                to={`/fixtures/${encodeURIComponent(statistic.fixtureId)}/statistics/${encodeURIComponent(statistic.statisticId)}`}
              >
                View calculation trace
              </Link>
            </li>
          ))}
        </ul>
      </details>
      <StatisticsDefinitions includeRunRate />
    </section>
  );
}

export function FixtureAnalytics({ statistics }: { statistics: FixtureStatistics }) {
  const innings = statistics.statistics
    .filter((statistic): statistic is InningsTeamStatistic => statistic.scope === 'innings')
    .sort((left, right) => left.inningsOrdinal - right.inningsOrdinal);
  const players = statistics.statistics.filter(
    (statistic): statistic is ParticipantFixtureStatistic => statistic.scope === 'participant',
  );

  return (
    <>
      <MatchSummary innings={innings} statistics={statistics} />
      {statistics.warnings.length > 0 ? (
        <section
          aria-labelledby="statistics-warnings-heading"
          className="statistics-warnings"
          role="status"
        >
          <h3 id="statistics-warnings-heading">Data notices</h3>
          <ul>
            {statistics.warnings.map((warning, index) => (
              <li key={`${warning.code}-${index}`}>{warning.message}</li>
            ))}
          </ul>
        </section>
      ) : null}
      {statistics.statistics.length === 0 ? (
        <div className="state-message" role="status">
          <h3>No match statistics available</h3>
          <p>No published standard-innings statistics are currently available for this match.</p>
        </div>
      ) : (
        <>
          <InningsSummary innings={innings} />
          <PowerplaySummary innings={innings} />
          <MatchLeaders players={players} />
          <BattingScorecards innings={innings} players={players} />
          <BowlingScorecards innings={innings} players={players} />
          <CalculationDetails statistics={statistics} />
        </>
      )}
    </>
  );
}
import {
  apiErrorResponseSchema,
  competitionCollectionResponseSchema,
  competitionResponseSchema,
  competitorCollectionResponseSchema,
  competitorResponseSchema,
  datasetReleaseCollectionResponseSchema,
  datasetReleaseResponseSchema,
  fixtureCollectionResponseSchema,
  fixtureResponseSchema,
  fixtureWeatherResponseSchema,
  fixtureStatisticResponseSchema,
  fixtureStatisticsResponseSchema,
  participantAggregatesResponseSchema,
  participantCollectionResponseSchema,
  participantFixtureCollectionResponseSchema,
  participantResponseSchema,
  seasonCollectionResponseSchema,
  seasonResponseSchema,
  type Competition,
  type Competitor,
  type DatasetRelease,
  type Fixture,
  type FixtureCollectionResponse,
  type FixtureWeather,
  type FixtureStatistic,
  type FixtureStatistics,
  type PaginationMetadata,
  type Participant,
  type ParticipantAggregateScope,
  type ParticipantAggregates,
  type ParticipantFixture,
  type Season,
} from '@sport-analytics/contracts';
import { ApiResponseError } from './client';

const apiBaseUrl = import.meta.env.VITE_API_BASE_URL ?? 'http://localhost:3000/api/v1';

export type FixtureEventExportFormat = 'csv' | 'json';
export type FixtureEventExportFilters = Partial<
  Pick<
    Record<'inningsId' | 'competitorId' | 'participantId' | 'overNumber' | 'wicketKind', string>,
    'inningsId' | 'competitorId' | 'participantId' | 'overNumber' | 'wicketKind'
  >
>;

function filenamePart(value: string): string {
  return value.replace(/[^a-zA-Z0-9_-]+/g, '-');
}

export function fixtureEventExportFilename(
  fixtureId: string,
  format: FixtureEventExportFormat,
  filters: FixtureEventExportFilters,
): string {
  const trace = [
    filters.inningsId ? `innings-${filenamePart(filters.inningsId)}` : null,
    filters.competitorId ? `team-${filenamePart(filters.competitorId)}` : null,
    filters.participantId ? `player-${filenamePart(filters.participantId)}` : null,
    filters.overNumber ? `over-${filenamePart(filters.overNumber)}` : null,
    filters.wicketKind ? `wicket-${filenamePart(filters.wicketKind)}` : null,
      signal,
    );
  },
  getParticipant(participantId: string, signal?: AbortSignal) {
    return requestPublicApi<{ data: Participant }>(
      `/participants/${encodeURIComponent(participantId)}`,
      participantResponseSchema,
      signal,
    );
  },
  listParticipantFixtures(participantId: string, search: string, signal?: AbortSignal) {
    return requestPublicApi<CollectionResponse<ParticipantFixture>>(
      `/participants/${encodeURIComponent(participantId)}/fixtures${search}`,
      participantFixtureCollectionResponseSchema,
      signal,
    );
  },
  // A single resource, not a collection: the endpoint returns every requested
  // level in one response, so there is no cursor to follow.
  getParticipantAggregates(
    participantId: string,
    scope?: ParticipantAggregateScope,
    signal?: AbortSignal,
  ) {
    return requestPublicApi<{ data: ParticipantAggregates }>(
      `/participants/${encodeURIComponent(participantId)}/statistics${scope ? `?scope=${scope}` : ''}`,
      participantAggregatesResponseSchema,
      signal,
    );
  },
};

