export function SectionError({
  description,
  reason,
  retry,
  retryLabel,
  title,
}: {
  description: string;
  reason?: string | undefined;
  retry(): void;
  retryLabel: string;
  title: string;
}) {
  return (
    <div className="state-message state-message--error" role="alert">
      <h3>{title}</h3>
